/* Near-straight shoulder wing of compound sweep, four engines buried two a side in the wing roots, and the tailplane carried high on a single fin.
   htail is "none" rather than the "high" the six existing ttail rows use, deliberately: addTail()'s ttail branch draws its own fin-top stabiliser and
   then falls through to the trailing `if (P.htail !== "none") stab(...)` at air3d_era.js:553, so "high" would hang a SECOND tailplane low on the body.
   The Valiant's is cruciform about two thirds up the fin, so one surface up there and nothing below it is the correct silhouette. */
gbr_e50_heavybomber: {era:"e50", fac:"gbr", role:"heavybomber", designation:"Vickers Valiant B.1", len:33.0, span:34.9, planform:"swept", sweep:25, taper:0.32, dihedral:2, prop:"none", engines:4, engMount:"wing", intake:"wingroot", tail:"ttail", htail:"none", wingpos:"shoulder", fuselage:"heavy", canard:false, rotodome:false, canoe:false, stealth:0, camo:"silver"},
/* A pure tailless delta of enormous area, four engines buried two a side in the wing roots, one broad fin on the spine and no tailplane anywhere. */
gbr_e60_heavybomber: {era:"e60", fac:"gbr", role:"heavybomber", designation:"Avro Vulcan B.2", len:30.5, span:33.8, planform:"delta", sweep:52, taper:0.12, dihedral:0, prop:"none", engines:4, engMount:"wing", intake:"wingroot", tail:"single", htail:"none", wingpos:"mid", fuselage:"heavy", canard:false, rotodome:false, canoe:false, stealth:0, camo:"white"},
/* The same delta in 1982 wraparound dark camouflage with the refuelling probe back on the nose. */
gbr_e80_heavybomber: {era:"e80", fac:"gbr", role:"heavybomber", designation:"Avro Vulcan B.2 (Black Buck)", len:30.5, span:33.8, planform:"delta", sweep:52, taper:0.12, dihedral:0, prop:"none", engines:4, engMount:"wing", intake:"wingroot", tail:"single", htail:"none", wingpos:"mid", fuselage:"heavy", canard:false, rotodome:false, canoe:false, stealth:0, camo:"green"},

/* A Mirage III scaled up by half: area-ruled waist, sixty-degree tailless delta, half-cone cheek intakes and one fin, two crew in tandem. */
fra_e60_heavybomber: {era:"e60", fac:"fra", role:"heavybomber", designation:"Dassault Mirage IVA", len:23.5, span:11.9, planform:"delta", sweep:60, taper:0.10, dihedral:0, prop:"none", engines:2, engMount:"fuselage", intake:"cheek", tail:"single", htail:"none", wingpos:"mid", fuselage:"area", canard:false, rotodome:false, canoe:false, stealth:0, camo:"silver"},
/* The same airframe in 1980s grey with the ASMP round on the centreline where the bomb used to sit. */
fra_e80_heavybomber: {era:"e80", fac:"fra", role:"heavybomber", designation:"Dassault Mirage IVP", len:23.5, span:11.9, planform:"delta", sweep:60, taper:0.10, dihedral:0, prop:"none", engines:2, engMount:"fuselage", intake:"cheek", tail:"single", htail:"none", wingpos:"mid", fuselage:"area", canard:false, rotodome:false, canoe:false, stealth:0, camo:"seagrey"},

/* Hercules: high wing, four big turboprops, a deep boxy hold and a ramp. */

if (a.def.role === "sead" || a.def.role === "ewair") return pickEmitter(a);
/* TERMINAL for the same reason, one role along. A strategic bomber whose
   every round is HELD is carrying release authority the owner asked for by
   name, and the branch below hunts the nearest harvester or heavy-armour
   contact - so without this a commander would put a megaton Yellow Sun or
   an AN-22 into an ore truck, and the gate would be decorative. It may
   have the war aim and nothing else, and not a RAID: warAim() returns a
   hauler when one scores higher than any structure, which is the same
   wrong answer arriving by a different road. Null drops it to the sweep
   branch, where the allWeaponsHeld guard holds it on the ramp - the same
   treatment the Weasel already gets.
   Gated on allWeaponsHeld so it changes nothing for the B-52 or the H-6:
   no existing heavybomber carries a held round. */
if (a.def.role === "heavybomber" && a.allWeaponsHeld && a.allWeaponsHeld()) {
  const st = warAim();
  if (!st || st.raid || !st.ref || st.ref.dead) return null;
  return st.ref.kind === "building" ? st.ref : null;
}

